// Every recording belongs to one paper and one Part. No global recording fallback.
const partAudioCache=new Map();let activeAudioKey='',audioDatabasePromise=null;
function partAudioKey(t,pi){return t.id+'::part-'+pi}
function audioDatabase(){if(!window.indexedDB)return Promise.resolve(null);if(audioDatabasePromise)return audioDatabasePromise;audioDatabasePromise=new Promise(resolve=>{let r=window.indexedDB.open('ielts-part-audio',1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('recordings'))r.result.createObjectStore('recordings',{keyPath:'key'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>resolve(null);r.onblocked=()=>resolve(null)});return audioDatabasePromise}
async function audioRead(key){let db=await audioDatabase();if(!db)return null;return new Promise(resolve=>{let r=db.transaction('recordings','readonly').objectStore('recordings').get(key);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>resolve(null)})}
async function audioWrite(record){let db=await audioDatabase();if(!db)return false;return new Promise(resolve=>{let tx=db.transaction('recordings','readwrite');tx.objectStore('recordings').put(record);tx.oncomplete=()=>resolve(true);tx.onerror=()=>resolve(false);tx.onabort=()=>resolve(false)})}
function makePartAudio(record){if(partAudioCache.has(record.key))return partAudioCache.get(record.key);let url=URL.createObjectURL(record.blob),element=document.createElement('audio');element.controls=true;element.src=url;element.setAttribute('aria-label',record.name);let item={...record,url,element};let lastSave=0;element.onloadedmetadata=()=>{let pos=read('ielts-audio-position',{})[record.key];if(Number.isFinite(pos)&&pos<element.duration)element.currentTime=pos};element.ontimeupdate=()=>{if(Date.now()-lastSave<2000)return;lastSave=Date.now();let pos=read('ielts-audio-position',{});pos[record.key]=element.currentTime;store('ielts-audio-position',pos)};element.onplay=()=>{for(const [key,r] of partAudioCache)if(key!==record.key)r.element.pause()};element.onerror=()=>toast('该 Part 的录音无法播放，请更换 MP3 或 WAV 文件');partAudioCache.set(record.key,item);return item}
async function getPartAudio(key){if(partAudioCache.has(key))return partAudioCache.get(key);let record=await audioRead(key);if(!record)return null;return makePartAudio(record)}
async function importPartAudio(t,pi,file){if(!file)return;let key=partAudioKey(t,pi),old=partAudioCache.get(key);if(old){old.element.pause();URL.revokeObjectURL(old.url);partAudioCache.delete(key)}let pos=read('ielts-audio-position',{});delete pos[key];store('ielts-audio-position',pos);let record={key,blob:file,name:file.name,updatedAt:Date.now()},item=makePartAudio(record),persisted=await audioWrite(record);item.persisted=persisted;let meta=read('ielts-audio-index',{});meta[key]={name:file.name,persisted};store('ielts-audio-index',meta);toast(`已为 C${t.book||''} Test ${t.testNumber||''} Part ${pi+1} 导入：${file.name}${persisted?'':'（本次页面内有效）'}`);if(view==='exam'&&session.testId===t.id&&partIndex===pi)renderExam();else if(view==='home')home();else if(view==='result'&&activeResult?.testId===t.id)showResult(activeResult)}
function selectActiveAudio(key){for(const [k,r] of partAudioCache)if(k!==key)r.element.pause();activeAudioKey=key;let item=partAudioCache.get(key);audio=item?.element||null;audioURL=item?.url||'';audioName=item?.name||'';return item}
const examWithoutPartAudio=renderExam;
renderExam=function(){let t=test();if(t.type!=='listening'){for(const item of partAudioCache.values())item.element.pause();audio=null;examWithoutPartAudio();return}let pi=partIndex,key=partAudioKey(t,pi),item=selectActiveAudio(key);examWithoutPartAudio();let label=$('.audio-select');if(label)label.firstChild.textContent=`Part ${pi+1} 选择音频`;let input=$('#audio-file');if(input)input.onchange=e=>importPartAudio(t,pi,e.target.files[0]);let mount=$('#audio-mount');if(mount){mount.dataset.partAudioKey=key;mount.setAttribute('title',item?`Part ${pi+1} · ${item.name}`:`Part ${pi+1} 尚未导入录音`);if(!item)mount.innerHTML=`<span class="muted">♬ Part ${pi+1} 尚未导入录音</span>`}getPartAudio(key).then(loaded=>{if(!loaded||view!=='exam'||session.testId!==t.id||partIndex!==pi||activeAudioKey!==key)return;audio=loaded.element;audioName=loaded.name;audioURL=loaded.url;let m=$('#audio-mount');if(m&&m.dataset.partAudioKey===key){m.replaceChildren(loaded.element);m.title=`Part ${pi+1} · ${loaded.name}`}})};
const homeWithoutAudioSlots=home;
home=function(){homeWithoutAudioSlots();document.querySelectorAll('.part-entry[data-test]').forEach(entry=>{let t=allTests().find(t=>t.id===entry.dataset.test),pi=+entry.dataset.pi;if(t?.type!=='listening')return;let key=partAudioKey(t,pi),meta=read('ielts-audio-index',{})[key],slot=document.createElement('label');slot.className='part-audio-slot';slot.title=meta?`Part ${pi+1}：${meta.name}`:`为 Part ${pi+1} 单独选择录音`;slot.innerHTML=`<span>♬ ${meta?'已选录音 · 更换':'＋ Part '+(pi+1)+' 音频'}</span>${meta?'<small>'+escapeHTML(meta.name)+'</small>':''}<input type="file" accept="audio/*" aria-label="C${t.book} Test ${t.testNumber} Part ${pi+1} 音频">`;slot.querySelector('input').onchange=e=>importPartAudio(t,pi,e.target.files[0]);entry.insertAdjacentElement('afterend',slot)})};
const reviewWithoutPartAudio=showResult;
showResult=function(h){reviewWithoutPartAudio(h);if(h.type!=='listening')return;let t=allTests().find(t=>t.id===h.testId);if(!t)return;let pi=reviewPart,key=partAudioKey(t,pi),bar=document.createElement('div');bar.className='review-audio-bar';bar.innerHTML=`<b>复听 Part ${pi+1}</b><span class="muted">正在读取该 Part 的录音…</span><label>选择 / 更换本 Part 录音<input type="file" accept="audio/*"></label>`;document.querySelector('.review-toolbar')?.insertAdjacentElement('afterend',bar);bar.querySelector('input').onchange=e=>importPartAudio(t,pi,e.target.files[0]);selectActiveAudio(key);getPartAudio(key).then(item=>{if(view!=='result'||activeResult?.id!==h.id||reviewPart!==pi)return;let status=bar.querySelector('.muted');if(!item){status.textContent=`Part ${pi+1} 尚未导入录音`;return}status.remove();bar.insertBefore(item.element,bar.querySelector('label'));bar.title=item.name;audio=item.element;activeAudioKey=key})};
home();
